DO $$
DECLARE
  rec RECORD;
  curr_points INT;
  curr_tier VARCHAR(20);
BEGIN
  FOR rec IN SELECT member_id FROM member_accounts ORDER BY member_id LOOP
    SELECT current_points, tier INTO curr_points, curr_tier FROM member_accounts WHERE member_id = rec.member_id;

    IF curr_points >= 5000 THEN
      UPDATE member_accounts SET tier = 'platinum', current_points = current_points - 500 WHERE member_id = rec.member_id;
    END IF;

    SELECT current_points, tier INTO curr_points, curr_tier FROM member_accounts WHERE member_id = rec.member_id;

    IF curr_points >= 2000 AND curr_tier != 'platinum' THEN
      UPDATE member_accounts SET tier = 'gold', current_points = current_points - 200 WHERE member_id = rec.member_id;
    END IF;

    SELECT current_points, tier INTO curr_points, curr_tier FROM member_accounts WHERE member_id = rec.member_id;

    IF curr_points < 500 AND curr_tier != 'bronze' THEN
      UPDATE member_accounts SET tier = 'bronze', current_points = current_points + 100 WHERE member_id = rec.member_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM member_accounts ORDER BY member_id;
